def _decimal(value):
    try:
        return Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        return None


def _usable_barcode(row):
    value = str(row.get('code') or '').strip()
    return bool(re.fullmatch(r'\d{8,14}', value) and len(set(value)) > 1)


def backfill_curation_state(apps, schema_editor):
    Product = apps.get_model('products', 'Product')
    Variant = apps.get_model('products', 'Variant')
    Store = apps.get_model('products', 'Store')
    StoreFulfillmentPolicy = apps.get_model('products', 'StoreFulfillmentPolicy')
    StoreVariantListing = apps.get_model('products', 'StoreVariantListing')

    Product.objects.filter(sku__startswith='LEGACY-P-').update(
        family_review_status='inferred'
    )
    Variant.objects.filter(requires_prescription=True).update(
        prescription_classification='prescription',
        prescription_review_status='inferred',
    )
    StoreFulfillmentPolicy.objects.bulk_create(
        [StoreFulfillmentPolicy(store_id=store_id) for store_id in Store.objects.values_list('id', flat=True)],
        batch_size=1000,
    )

    updates = []
    false_like = {'', '0', 'false', 'no', '0000-00-00'}
    for listing in StoreVariantListing.objects.iterator(chunk_size=1000):
        rows = (listing.raw_data or {}).get('rows') or []
        flags = set()
        if rows and not any(_usable_barcode(row) for row in rows):
            flags.add('missing_or_invalid_barcode')
        if listing.is_active and listing.price == Decimal('0'):
            flags.add('zero_active_price')
        if any(
            (_decimal(row.get('price')) or Decimal('0')) >= Decimal('99999999.99')
            for row in rows
        ):
            flags.add('sentinel_price')
        if any(
            value is not None and value < 0
            for value in (_decimal(row.get('buying')) for row in rows)
        ):
            flags.add('negative_cost')
        if any(
            value is not None and value < 0
            for value in (_decimal(row.get('left_p')) for row in rows)
        ):
            flags.add('negative_stock')
        if any(
            value is not None and (value < 0 or value > 100)
            for value in (_decimal(row.get('vat')) for row in rows)
        ):
            flags.add('implausible_vat')
        if any(
            str(row.get(field_name) or '').strip().casefold() not in false_like
            for row in rows
            for field_name in ('promotion', 'promo', 'prom', 'start', 'end')
        ):
            flags.add('legacy_promotion_unmapped')
        if any(str(row.get('kra') or '').strip() for row in rows):
            flags.add('unmapped_kra_classification')

        listing.data_quality_flags = sorted(flags)
        listing.review_status = 'needs_review' if flags else 'unreviewed'
        updates.append(listing)
        if len(updates) == 1000:
            StoreVariantListing.objects.bulk_update(
                updates, ['data_quality_flags', 'review_status'], batch_size=1000
            )
            updates = []
    if updates:
        StoreVariantListing.objects.bulk_update(
            updates, ['data_quality_flags', 'review_status'], batch_size=1000
        )


